local function bvBe32(value)
    value %= BV_U32
    return BV_CHAR(
        BV_RSHIFT(value, 24) % 256,
        BV_RSHIFT(value, 16) % 256,
        BV_RSHIFT(value, 8) % 256,
        value % 256
    )
end

local function bvSha256(source)
    local sourceLength = #source
    local paddingLength = (56 - ((sourceLength + 1) % 64)) % 64
    local bitHigh = BV_FLOOR(sourceLength / 536870912)
    local bitLow = (sourceLength * 8) % BV_U32
    source ..= BV_CHAR(128) .. string.rep('\0', paddingLength) .. bvBe32(bitHigh) .. bvBe32(bitLow)

    local h1, h2, h3, h4 = 0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a
    local h5, h6, h7, h8 = 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19
    local words = table.create(64, 0)
    for offset = 1, #source, 64 do
        if BV_UNPACK then
            local w1, w2, w3, w4, w5, w6, w7, w8,
                w9, w10, w11, w12, w13, w14, w15, w16 =
                BV_UNPACK(BV_SHA_UNPACK_FORMAT, source, offset)
            words[1], words[2], words[3], words[4] = w1, w2, w3, w4
            words[5], words[6], words[7], words[8] = w5, w6, w7, w8
            words[9], words[10], words[11], words[12] = w9, w10, w11, w12
            words[13], words[14], words[15], words[16] = w13, w14, w15, w16
        else
            for index = 0, 15 do
                local a, b, c, d = BV_BYTE(source, offset + index * 4, offset + index * 4 + 3)
                words[index + 1] = a * 16777216 + b * 65536 + c * 256 + d
            end
        end
        for index = 17, 64 do
            local left = words[index - 15]
            local right = words[index - 2]
            local s0 = BV_BXOR(BV_RROTATE(left, 7), BV_RROTATE(left, 18), BV_RSHIFT(left, 3))
            local s1 = BV_BXOR(BV_RROTATE(right, 17), BV_RROTATE(right, 19), BV_RSHIFT(right, 10))
            words[index] = BV_BXOR(words[index - 16] + s0 + words[index - 7] + s1, 0)
        end

        local a, b, c, d, e, f, g, h = h1, h2, h3, h4, h5, h6, h7, h8
        for index = 1, 64 do
            local s1 = BV_BXOR(BV_RROTATE(e, 6), BV_RROTATE(e, 11), BV_RROTATE(e, 25))
            local choice = BV_BXOR(BV_BAND(e, f), BV_BAND(BV_BNOT(e), g))
            local temp1 = BV_BXOR(h + s1 + choice + BV_SHA_K[index] + words[index], 0)
            local s0 = BV_BXOR(BV_RROTATE(a, 2), BV_RROTATE(a, 13), BV_RROTATE(a, 22))
            local majority = BV_BXOR(BV_BAND(a, b), BV_BAND(a, c), BV_BAND(b, c))
            local temp2 = BV_BXOR(s0 + majority, 0)
            h, g, f, e, d, c, b, a = g, f, e, BV_BXOR(d + temp1, 0), c, b, a, BV_BXOR(temp1 + temp2, 0)
        end
        h1, h2, h3, h4 = BV_BXOR(h1 + a, 0), BV_BXOR(h2 + b, 0), BV_BXOR(h3 + c, 0), BV_BXOR(h4 + d, 0)
        h5, h6, h7, h8 = BV_BXOR(h5 + e, 0), BV_BXOR(h6 + f, 0), BV_BXOR(h7 + g, 0), BV_BXOR(h8 + h, 0)
    end
    return bvBe32(h1) .. bvBe32(h2) .. bvBe32(h3) .. bvBe32(h4)
        .. bvBe32(h5) .. bvBe32(h6) .. bvBe32(h7) .. bvBe32(h8)
end

local function bvHmacSha256(key, message)
    if #key > 64 then key = bvSha256(key) end
    key ..= string.rep('\0', 64 - #key)
    local inner, outer = table.create(64), table.create(64)
    for index = 1, 64 do
        local value = BV_BYTE(key, index)
        inner[index] = BV_CHAR(BV_BXOR(value, 0x36))
        outer[index] = BV_CHAR(BV_BXOR(value, 0x5c))
    end
    return bvSha256(table.concat(outer) .. bvSha256(table.concat(inner) .. message))
end

local BV_HEX = '0123456789abcdef'
local function bvBytesToHex(source)
    local output = table.create(#source * 2)
    for index = 1, #source do
        local value = BV_BYTE(source, index)
        local high = BV_FLOOR(value / 16)
        output[index * 2 - 1] = BV_SUB(BV_HEX, high + 1, high + 1)
        output[index * 2] = BV_SUB(BV_HEX, value - high * 16 + 1, value - high * 16 + 1)
    end
    return table.concat(output)
end

local function bvHexValue(value)
    if value >= 48 and value <= 57 then return value - 48 end
    if value >= 65 and value <= 70 then return value - 55 end
    if value >= 97 and value <= 102 then return value - 87 end
end

local function bvHexToBytes(source, expectedBytes)
    if type(source) ~= 'string' or #source % 2 ~= 0 then return nil end
    if expectedBytes and #source ~= expectedBytes * 2 then return nil end
    local output = table.create(#source / 2)
    for index = 1, #source, 2 do
        local high, low = bvHexValue(BV_BYTE(source, index)), bvHexValue(BV_BYTE(source, index + 1))
        if high == nil or low == nil then return nil end
        output[(index + 1) / 2] = BV_CHAR(high * 16 + low)
    end
    return table.concat(output)
end

local function bvConstantEqual(left, right)
    if type(left) ~= 'string' or type(right) ~= 'string' or #left ~= #right then return false end
    local difference = 0
    for index = 1, #left do difference = BV_BOR(difference, BV_BXOR(BV_BYTE(left, index), BV_BYTE(right, index))) end
    return difference == 0
end

local function bvXorBytes(left, right)
    if #left ~= #right then return nil end
    local output = table.create(#left)
    for index = 1, #left do output[index] = BV_CHAR(BV_BXOR(BV_BYTE(left, index), BV_BYTE(right, index))) end
    return table.concat(output)
end

local BV_BASE85 = [==[!"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\^_`abcdefghijklmnopqrstuv]==]
local BV_BASE85_MAP = {}
for index = 1, #BV_BASE85 do BV_BASE85_MAP[BV_BYTE(BV_BASE85, index)] = index - 1 end

local function bvBase85Decode(source, expectedSize)
    local output, written, index = BV_CREATE(expectedSize), 0, 1
    while index <= #source do
        local remaining = #source - index + 1
        local count = remaining >= 5 and 5 or remaining
        if count == 1 then return nil end
        local value = 0
        for digitIndex = 0, 4 do
            local digit = 84
            if digitIndex < count then
                digit = BV_BASE85_MAP[BV_BYTE(source, index + digitIndex)]
                if digit == nil then return nil end
            end
            value = value * 85 + digit
        end
        local emitted = count < 5 and count - 1 or 4
        if written + emitted > expectedSize then return nil end
        if emitted == 4 and BV_NATIVE_WORDS then
            -- Base85 groups are big-endian on the wire while buffer words are
            -- little-endian.  One native write replaces four byte writes.
            BV_WRITEU32(output, written,
                (value % 256) * 16777216
                    + (BV_FLOOR(value / 256) % 256) * 65536
                    + (BV_FLOOR(value / 65536) % 256) * 256
                    + BV_FLOOR(value / 16777216) % 256
            )
            written += 4
        else
            if emitted >= 1 then
                BV_WRITEU8(output, written, BV_FLOOR(value / 16777216) % 256)
                written += 1
            end
            if emitted >= 2 then
                BV_WRITEU8(output, written, BV_FLOOR(value / 65536) % 256)
                written += 1
            end
            if emitted >= 3 then
                BV_WRITEU8(output, written, BV_FLOOR(value / 256) % 256)
                written += 1
            end
            if emitted >= 4 then
                BV_WRITEU8(output, written, value % 256)
                written += 1
            end
        end
        index += 5
    end
    if written ~= expectedSize then return nil end
    return output
end

local function bvReadU32LE(source, offset)
    return BV_BYTE(source, offset)
        + BV_BYTE(source, offset + 1) * 256
        + BV_BYTE(source, offset + 2) * 65536
        + BV_BYTE(source, offset + 3) * 16777216
end

local function bvQuarterRound(state, a, b, c, d)
    state[a] = (state[a] + state[b]) % BV_U32
    state[d] = BV_LROTATE(BV_BXOR(state[d], state[a]), 16)
    state[c] = (state[c] + state[d]) % BV_U32
    state[b] = BV_LROTATE(BV_BXOR(state[b], state[c]), 12)
    state[a] = (state[a] + state[b]) % BV_U32
    state[d] = BV_LROTATE(BV_BXOR(state[d], state[a]), 8)
    state[c] = (state[c] + state[d]) % BV_U32
    state[b] = BV_LROTATE(BV_BXOR(state[b], state[c]), 7)
end

-- The table-based quarter round above is kept for the pure-Luau fallback.
-- Native byte stores can keep the sixteen ChaCha words in locals instead;
-- returning four values avoids the table indexing that dominates obfuscated
-- executor runtimes.
local function bvQuarterRoundValues(a, b, c, d)
    -- bit32 operations truncate to a 32-bit word at each use, so keeping the
    -- short-lived additions as numbers avoids a modulo on every quarter
    -- round while preserving ChaCha20's unsigned-word arithmetic.
    a = a + b
    d = BV_LROTATE(BV_BXOR(d, a), 16)
    c = c + d
    b = BV_LROTATE(BV_BXOR(b, c), 12)
    a = a + b
    d = BV_LROTATE(BV_BXOR(d, a), 8)
    c = c + d
    b = BV_LROTATE(BV_BXOR(b, c), 7)
    return a, b, c, d
end

local function bvChaCha20(input, inputSize, key, nonce)
    if #key ~= 32 or #nonce ~= 12 then return nil end
    if BV_NATIVE_WORDS then
        local k0, k1, k2, k3 = bvReadU32LE(key, 1), bvReadU32LE(key, 5), bvReadU32LE(key, 9), bvReadU32LE(key, 13)
        local k4, k5, k6, k7 = bvReadU32LE(key, 17), bvReadU32LE(key, 21), bvReadU32LE(key, 25), bvReadU32LE(key, 29)
        local n0, n1, n2 = bvReadU32LE(nonce, 1), bvReadU32LE(nonce, 5), bvReadU32LE(nonce, 9)
        local output, counter = BV_CREATE(inputSize), 1
        local qr = bvQuarterRoundValues
        for offset = 0, inputSize - 1, 64 do
            local x0, x1, x2, x3 = 0x61707865, 0x3320646e, 0x79622d32, 0x6b206574
            local x4, x5, x6, x7 = k0, k1, k2, k3
            local x8, x9, x10, x11 = k4, k5, k6, k7
            local x12, x13, x14, x15 = counter, n0, n1, n2
